const scan=JSON.parse(fs.readFileSync('.understand-anything/intermediate/scan-result.json','utf8'));
const review=JSON.parse(fs.readFileSync('.understand-anything/intermediate/review.json','utf8'));
const meta={
  lastAnalyzedAt: graph.project.analyzedAt,
  gitCommitHash: graph.project.gitCommitHash,
  version: graph.version,
  analyzedFiles: scan.files.length
};
fs.writeFileSync('.understand-anything/meta.json', JSON.stringify(meta,null,2)+'\n');
const countBy=(arr,key)=>arr.reduce((a,x)=>{const k=x[key]||'unknown'; a[k]=(a[k]||0)+1; return a;},{});
const summary={
  project: graph.project,
  filesAnalyzed: scan.files.length,
  totalFiles: scan.totalFiles,
  fileCategories: countBy(scan.files,'fileCategory'),
  nodes: graph.nodes.length,
  nodeTypes: countBy(graph.nodes,'type'),
  edges: graph.edges.length,
  edgeTypes: countBy(graph.edges,'type'),
  layers: graph.layers.map(l=>({name:l.name,count:l.nodeIds.length})),
  tourSteps: graph.tour.length,
  warnings: review.warnings || [],
  issues: review.issues || []
};
fs.writeFileSync('.understand-anything/tmp/final-summary.json', JSON.stringify(summary,null,2)+'\n');
console.log(JSON.stringify(summary,null,2));
